<?php

declare(strict_types=1);

namespace ValeApp\App\Commands;

use Doctrine\DBAL\Connection;
use Symfony\Component\Console\Command\Command;
use Symfony\Component\Console\Input\InputInterface;
use Symfony\Component\Console\Input\InputOption;
use Symfony\Component\Console\Output\OutputInterface;
use Symfony\Component\Console\Style\SymfonyStyle;
use ValeApp\Infrastructure\Persistence\DbalSettingsRepository;

/**
 * Remove all WebP renditions that were auto-generated by the CMS.
 *
 * Runs only while the "Convert images to WebP" setting (media_webp_enabled)
 * is OFF. It deletes the derived WebP files (full-size webp plus the
 * webp_small/webp_medium/webp_large thumbnails) and prunes those keys from
 * each media record's thumbnails map, falling the site back to the original
 * formats. WebP files uploaded directly by the user (no non-WebP original
 * sibling) are treated as original media and are never touched.
 */
final class MediaWebpRemoveCommand extends Command
{
    private const WEBP_VARIANT_KEYS = ['webp', 'webp_small', 'webp_medium', 'webp_large'];

    public function __construct(
        private readonly Connection $db,
        private readonly DbalSettingsRepository $settings,
        private readonly string $uploadDir,
    ) {
        parent::__construct();
    }

    protected function configure(): void
    {
        $this
            ->setName('media:webp-remove')
            ->setDescription('Remove auto-generated WebP renditions when the WebP setting is off')
            ->addOption(
                'dry-run',
                null,
                InputOption::VALUE_NONE,
                'Only report what would be deleted, do not change any files or records',
            );
    }

    protected function execute(InputInterface $input, OutputInterface $output): int
    {
        $io     = new SymfonyStyle($input, $output);
        $dryRun = (bool) $input->getOption('dry-run');

        $io->title('Remove Auto-Generated WebP');

        if ($this->settings->get('media_webp_enabled', '0') === '1') {
            $io->error('WebP conversion is currently ENABLED. Turn off "Convert images to WebP" (media_webp_enabled) in admin settings first, then re-run this command.');
            return Command::FAILURE;
        }

        $io->text(sprintf('Mode: <info>%s</info>', $dryRun ? 'dry-run (no changes)' : 'live'));

        $deletedFiles = [];
        $updatedIds   = [];
        $skippedOwned = [];

        $rows = $this->db->fetchAllAssociative(
            'SELECT id, path, thumbnails FROM ' . VL_DB_PREFIX . 'media',
        );

        $uploadDir = rtrim($this->uploadDir, '/');

        foreach ($rows as $row) {
            $id     = (int) $row['id'];
            $path   = str_replace('\\', '/', (string) $row['path']);
            $thumbs = !empty($row['thumbnails']) ? json_decode((string) $row['thumbnails'], true) : [];
            if (!is_array($thumbs)) {
                $thumbs = [];
            }

            // Collect every derived WebP variant path referenced by this record.
            $variantRelPaths = [];
            foreach (self::WEBP_VARIANT_KEYS as $key) {
                if (isset($thumbs[$key]) && is_string($thumbs[$key]) && $thumbs[$key] !== '') {
                    $variantRelPaths[] = str_replace('\\', '/', $thumbs[$key]);
                }
            }

            // Also pick up the full-size WebP conversion that sits next to the
            // original (same basename, different extension) even when it is not
            // referenced in the thumbnails map — e.g. legacy rows.
            if (isset($thumbs['webp']) && is_string($thumbs['webp'])) {
                $variantRelPaths[] = str_replace('\\', '/', $thumbs['webp']);
            }

            $variantRelPaths = array_values(array_unique($variantRelPaths));

            $dbPathAbs   = $uploadDir . '/' . ltrim($path, '/');
            $dbBase      = pathinfo($path, PATHINFO_FILENAME);
            $dbExt       = strtolower(pathinfo($path, PATHINFO_EXTENSION));

            // Determine whether this DB record itself is a user-uploaded WebP
            // (no sibling non-WebP original registered). Such files are originals
            // and must never be deleted.
            $isOwnedWebp = $dbExt === 'webp' && !$this->hasNonWebpSiblingInDb($path, $rows);

            // Files to delete on disk: all referenced variants, plus the
            // full-size webp sibling of a non-WebP original record.
            $toDelete = [];
            foreach ($variantRelPaths as $rel) {
                $toDelete[$rel] = true;
            }

            if ($dbExt !== 'webp' && !$isOwnedWebp) {
                $sibling = $uploadDir . '/' . ltrim(dirname($path), '.') . '/' . pathinfo($path, PATHINFO_FILENAME) . '.webp';
                $sibling = preg_replace('#/+#', '/', str_replace('\\', '/', $sibling));
                if (!str_ends_with($dbPathAbs, '.webp') && is_file($sibling)) {
                    $relSibling            = ltrim(str_replace('\\', '/', substr($sibling, strlen($uploadDir))), '/');
                    $toDelete[$relSibling] = true;
                }
            }

            // Remove owned record's own file path from deletion list.
            unset($toDelete[ltrim($path, '/')]);

            // Never delete user-owned WebP originals.
            if ($isOwnedWebp) {
                unset($toDelete[ltrim($path, '/')]);
                $skippedOwned[] = $path;
            }

            // Prune variant keys from the thumbnails map.
            $newThumbs = $thumbs;
            foreach (self::WEBP_VARIANT_KEYS as $key) {
                unset($newThumbs[$key]);
            }

            $changedDb = $newThumbs !== $thumbs;

            if ($toDelete !== [] || $changedDb) {
                if ($dryRun) {
                    $io->writeln(sprintf('  <comment>Would update:</comment> %s', $path));
                    foreach (array_keys($toDelete) as $rel) {
                        $io->writeln(sprintf('    <comment>  delete:</comment> %s', $rel));
                    }
                    $updatedIds[] = $id;
                    continue;
                }

                $deletedLocal = [];
                foreach (array_keys($toDelete) as $rel) {
                    $abs = $uploadDir . '/' . ltrim($rel, '/');
                    if (is_file($abs) && @unlink($abs)) {
                        $deletedLocal[] = $rel;
                    }
                }

                if ($changedDb) {
                    $this->db->update(VL_DB_PREFIX . 'media', [
                        'thumbnails' => json_encode($newThumbs),
                    ], ['id' => $id]);
                }

                $io->writeln(sprintf('  <info>Updated:</info> %s', $path));
                foreach ($deletedLocal as $rel) {
                    $io->writeln(sprintf('    <info>  deleted:</info> %s', $rel));
                }
                $deletedFiles = array_merge($deletedFiles, $deletedLocal);
                $updatedIds[] = $id;
            }
        }

        $io->section('Results');
        $io->writeln(sprintf('  Records updated: <info>%d</info>', count($updatedIds)));
        $io->writeln(sprintf('  Files deleted:   <info>%d</info>', count($deletedFiles)));
        $io->writeln(sprintf('  Owned WebP kept: <comment>%d</comment>', count($skippedOwned)));

        if ($skippedOwned !== []) {
            $io->note('These WebP files are treated as originally uploaded and were kept:');
            foreach ($skippedOwned as $p) {
                $io->writeln(sprintf('  - %s', $p));
            }
        }

        if ($dryRun) {
            $io->warning('Dry-run complete. No changes were made.');
        }

        $io->success('Done.');
        return Command::SUCCESS;
    }

    /**
     * @param array<int, array{id: mixed, path: mixed, thumbnails: mixed}> $rows
     */
    private function hasNonWebpSiblingInDb(string $path, array $rows): bool
    {
        $base = pathinfo($path, PATHINFO_FILENAME);
        $dir  = dirname($path);
        foreach ($rows as $row) {
            $other = str_replace('\\', '/', (string) $row['path']);
            if ($other === $path) {
                continue;
            }
            if (
                dirname($other)                        === $dir
                && pathinfo($other, PATHINFO_FILENAME) === $base
                && strtolower(pathinfo($other, PATHINFO_EXTENSION)) !== 'webp'
            ) {
                return true;
            }
        }
        return false;
    }
}
